1	'use client';
2	
3	import { useState } from 'react';
4	import { Save, Check, Building2, User, Bell, DollarSign, Mail, Smartphone, X, Plus } from 'lucide-react';
5	import { facility, manager } from '@/lib/dummyData';
6	import { useLocalStorage } from '@/lib/useLocalStorage';
7	
8	const STATES = ['NSW','VIC','QLD','SA','WA','TAS','NT','ACT'];
9	
10	const DEFAULT_EMAIL_RECIPIENTS = [
11	  { id: 1, email: 'jennifer@sunriseagedcare.com.au', active: true },
12	  { id: 2, email: 'operations@sunriseagedcare.com.au', active: true },
13	];
14	const DEFAULT_SMS_RECIPIENTS = [
15	  { id: 1, mobile: '0412 345 678', active: true },
16	];
17	
18	// ── Helper components defined OUTSIDE the page component to prevent remounting on re-render ──
19	
20	function SectionCard({ icon: Icon, title, children }) {
21	  return (
22	    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5 mb-6 transition-shadow hover:shadow-md">
23	      <div className="flex items-center gap-2 mb-5 pb-3 border-b border-gray-100">
24	        <Icon className="w-4 h-4 text-[#22c55e]" />
25	        <h2 className="font-semibold text-gray-900">{title}</h2>
26	      </div>
27	      {children}
28	    </div>
29	  );
30	}
31	
32	function Field({ label, hint, children }) {
33	  return (
34	    <div>
35	      <label className="block text-xs font-medium text-gray-600 mb-1">{label}</label>
36	      {hint && <p className="text-xs text-gray-400 mb-1.5">{hint}</p>}
37	      {children}
38	    </div>
39	  );
40	}
41	
42	function SettingsInput({ value, onChange, placeholder, type = 'text', ...rest }) {
43	  return (
44	    <input
45	      type={type}
46	      value={value}
47	      onChange={onChange}
48	      placeholder={placeholder}
49	      {...rest}
50	      className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#22c55e] transition"
51	    />
52	  );
53	}
54	
55	function Toggle({ checked, onChange, label }) {
56	  return (
57	    <label className="flex items-center gap-3 cursor-pointer group">
58	      <div className="relative">
59	        <input type="checkbox" className="sr-only" checked={checked} onChange={onChange} />
60	        <div className={`w-11 h-6 rounded-full transition-colors duration-200 ${checked ? 'bg-[#22c55e]' : 'bg-gray-200'}`} />
61	        <div className={`absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full shadow transition-transform duration-200 ${checked ? 'translate-x-5' : ''}`} />
62	      </div>
63	      {label && <span className="text-sm text-gray-700">{label}</span>}
64	    </label>
65	  );
66	}
67	
68	function SmallToggle({ checked, onChange }) {
69	  return (
70	    <label className="flex items-center gap-1.5 cursor-pointer">
71	      <div className="relative">
72	        <input type="checkbox" className="sr-only" checked={checked} onChange={onChange} />
73	        <div className={`w-8 h-4 rounded-full transition-colors duration-200 ${checked ? 'bg-[#22c55e]' : 'bg-gray-200'}`} />
74	        <div className={`absolute top-0.5 left-0.5 w-3 h-3 bg-white rounded-full shadow transition-transform duration-200 ${checked ? 'translate-x-4' : ''}`} />
75	      </div>
76	      <span className="text-xs text-gray-500">{checked ? 'Active' : 'Inactive'}</span>
77	    </label>
78	  );
79	}
80	
81	function SaveButton({ saving, saved, onClick, label = 'Save Settings' }) {
82	  return (
83	    <button
84	      type="button"
85	      onClick={onClick}
86	      disabled={saving}
87	      className="flex items-center gap-2 px-6 py-2.5 bg-[#22c55e] text-white rounded-lg text-sm font-semibold hover:bg-green-600 active:bg-green-700 transition-colors disabled:opacity-60 shadow-sm w-full sm:w-auto justify-center"
88	    >
89	      {saving ? (
90	        <><span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> Saving…</>
91	      ) : saved ? (
92	        <><Check className="w-4 h-4" /> Saved!</>
93	      ) : (
94	        <><Save className="w-4 h-4" /> {label}</>
95	      )}
96	    </button>
97	  );
98	}
99	
100	export default function SettingsPage() {
101	  const [saved,   setSaved]   = useState(false);
102	  const [saving,  setSaving]  = useState(false);
103	
104	  // Facility details — persisted to localStorage
105	  const [facName,     setFacName]     = useLocalStorage('cm_facName',    facility.name);
106	  const [abn,         setAbn]         = useLocalStorage('cm_abn',        facility.abn);
107	  const [state,       setState]       = useLocalStorage('cm_state',      facility.state);
108	  const [address,     setAddress]     = useLocalStorage('cm_address',    facility.address);
109	  const [postcode,    setPostcode]    = useLocalStorage('cm_postcode',   facility.postcode);
110	  const [residents,   setResidents]   = useLocalStorage('cm_residents',  String(facility.residentCount));
111	
112	  // Manager details
113	  const [mgName,      setMgName]      = useLocalStorage('cm_mgName',     manager.name);
114	  const [mgEmail,     setMgEmail]     = useLocalStorage('cm_mgEmail',    manager.email);
115	  const [mgPhone,     setMgPhone]     = useLocalStorage('cm_mgPhone',    manager.phone);
116	
117	  // Alert preferences
118	  const [alertTime,   setAlertTime]   = useLocalStorage('cm_alertTime',  '07:00');
119	  const [emailAlerts, setEmailAlerts] = useLocalStorage('cm_emailAlerts', true);
120	  const [smsAlerts,   setSmsAlerts]   = useLocalStorage('cm_smsAlerts',  false);
121	  const [smsPhone,    setSmsPhone]    = useLocalStorage('cm_smsPhone',   '');
122	
123	  // AN-ACC
124	  const [anAccRate,   setAnAccRate]   = useLocalStorage('cm_anAccRate',  String(facility.anAccRate));
125	
126	  // ── Alert Recipients ────────────────────────────────────────────────────────
127	  const [emailRecipients, setEmailRecipients] = useLocalStorage('cm_emailRecipients', DEFAULT_EMAIL_RECIPIENTS);
128	  const [smsRecipients,   setSmsRecipients]   = useLocalStorage('cm_smsRecipients',   DEFAULT_SMS_RECIPIENTS);
129	  const [newEmail,        setNewEmail]        = useState('');
130	  const [emailError,      setEmailError]      = useState('');
131	  const [newMobile,       setNewMobile]       = useState('');
132	  const [mobileError,     setMobileError]     = useState('');
133	  const [recipientsSaved, setRecipientsSaved] = useState(false);
134	  const [recipientsSaving, setRecipientsSaving] = useState(false);
135	
136	  function handleSave(e) {
137	    e.preventDefault();
138	    setSaving(true);
139	    setTimeout(() => {
140	      setSaving(false);
141	      setSaved(true);
142	      setTimeout(() => setSaved(false), 3000);
143	    }, 800);
144	  }
145	
146	  // ── Email recipient handlers ──────────────────────────────────────────────
147	  function validateEmail(email) {
148	    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
149	  }
150	
151	  function addEmail() {
152	    const trimmed = newEmail.trim();
153	    if (!validateEmail(trimmed)) {
154	      setEmailError('Please enter a valid email address.');
155	      return;
156	    }
157	    if (emailRecipients.length >= 5) {
158	      setEmailError('Maximum 5 email recipients allowed.');
159	      return;
160	    }
161	    if (emailRecipients.some(r => r.email.toLowerCase() === trimmed.toLowerCase())) {
162	      setEmailError('This email address is already in the list.');
163	      return;
164	    }
165	    setEmailRecipients(prev => [...prev, { id: Date.now(), email: trimmed, active: true }]);
166	    setNewEmail('');
167	    setEmailError('');
168	  }
169	
170	  function removeEmail(id) {
171	    setEmailRecipients(prev => prev.filter(r => r.id !== id));
172	  }
173	
174	  function toggleEmail(id) {
175	    setEmailRecipients(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));
176	  }
177	
178	  // ── SMS recipient handlers ────────────────────────────────────────────────
179	  function validateMobile(mobile) {
180	    return /^04\d{2}\s?\d{3}\s?\d{3}$/.test(mobile.trim());
181	  }
182	
183	  function addMobile() {
184	    const trimmed = newMobile.trim();
185	    if (!validateMobile(trimmed)) {
186	      setMobileError('Enter a valid Australian mobile number (04XX XXX XXX).');
187	      return;
188	    }
189	    if (smsRecipients.length >= 3) {
190	      setMobileError('Maximum 3 SMS recipients allowed.');
191	      return;
192	    }
193	    if (smsRecipients.some(r => r.mobile.replace(/\s/g,'') === trimmed.replace(/\s/g,''))) {
194	      setMobileError('This mobile number is already in the list.');
195	      return;
196	    }
197	    setSmsRecipients(prev => [...prev, { id: Date.now(), mobile: trimmed, active: true }]);
198	    setNewMobile('');
199	    setMobileError('');
200	  }
201	
202	  function removeMobile(id) {
203	    setSmsRecipients(prev => prev.filter(r => r.id !== id));
204	  }
205	
206	  function toggleMobile(id) {
207	    setSmsRecipients(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));
208	  }
209	
210	  function handleRecipientsSave() {
211	    setRecipientsSaving(true);
212	    setTimeout(() => {
213	      setRecipientsSaving(false);
214	      setRecipientsSaved(true);
215	      setTimeout(() => setRecipientsSaved(false), 3000);
216	    }, 800);
217	  }
218	
219	  return (
220	    <div className="p-4 md:p-6 max-w-3xl mx-auto">
221	
222	      <div className="mb-6">
223	        <h1 className="text-xl font-bold text-gray-900">Facility Settings</h1>
224	        <p className="text-sm text-gray-500 mt-0.5">Manage your facility configuration and preferences</p>
225	      </div>
226	
227	      <form onSubmit={handleSave}>
228	
229	        {/* ── Facility Details ── */}
230	        <SectionCard icon={Building2} title="Facility Details">
231	          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
232	            <div className="sm:col-span-2">
233	              <Field label="Facility Name">
234	                <SettingsInput value={facName} onChange={e => setFacName(e.target.value)} placeholder="Sunrise Aged Care" />
235	              </Field>
236	            </div>
237	            <Field label="ABN">
238	              <SettingsInput value={abn} onChange={e => setAbn(e.target.value)} placeholder="12 345 678 901" />
239	            </Field>
240	            <Field label="State">
241	              <select
242	                value={state}
243	                onChange={e => setState(e.target.value)}
244	                className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#22c55e] bg-white"
245	              >
246	                {STATES.map(s => <option key={s}>{s}</option>)}
247	              </select>
248	            </Field>
249	            <div className="sm:col-span-2">
250	              <Field label="Street Address">
251	                <SettingsInput value={address} onChange={e => setAddress(e.target.value)} placeholder="42 Sunrise Boulevard" />
252	              </Field>
253	            </div>
254	            <Field label="Postcode (4 digits)">
255	              <SettingsInput
256	                value={postcode}
257	                onChange={e => setPostcode(e.target.value.replace(/\D/,'').slice(0,4))}
258	                placeholder="2150"
259	                maxLength={4}
260	              />
261	            </Field>
262	            <Field label="Number of Residents">
263	              <SettingsInput
264	                type="number"
265	                value={residents}
266	                onChange={e => setResidents(e.target.value)}
267	                placeholder="40"
268	                min="1" max="500"
269	              />
270	            </Field>
271	          </div>
272	        </SectionCard>
273	
274	        {/* ── Manager Details ── */}
275	        <SectionCard icon={User} title="Manager Details">
276	          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
277	            <div className="sm:col-span-2">
278	              <Field label="Manager Name">
279	                <SettingsInput value={mgName} onChange={e => setMgName(e.target.value)} placeholder="Jennifer Roberts" />
280	              </Field>
281	            </div>
282	            <Field label="Email Address">
283	              <SettingsInput type="email" value={mgEmail} onChange={e => setMgEmail(e.target.value)} placeholder="jennifer@facility.com.au" />
284	            </Field>
285	            <Field label="Phone (04XX XXX XXX)">
286	              <SettingsInput value={mgPhone} onChange={e => setMgPhone(e.target.value)} placeholder="0412 345 678" />
287	            </Field>
288	          </div>
289	        </SectionCard>
290	
291	        {/* ── Alert Preferences ── */}
292	        <SectionCard icon={Bell} title="Alert Preferences">
293	          <div className="space-y-4">
294	            <Field label="Daily Alert Time (AEST)" hint="AI gap analysis is sent to your email at this time each morning">
295	              <input
296	                type="time"
297	                value={alertTime}
298	                onChange={e => setAlertTime(e.target.value)}
299	                className="border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#22c55e] w-full sm:w-auto"
300	              />
301	            </Field>
302	            <div className="space-y-3">
303	              <Toggle
304	                checked={emailAlerts}
305	                onChange={() => setEmailAlerts(v => !v)}
306	                label="Email alerts"
307	              />
308	              <Toggle
309	                checked={smsAlerts}
310	                onChange={() => setSmsAlerts(v => !v)}
311	                label="SMS alerts (Growth plan only)"
312	              />
313	            </div>
314	            {smsAlerts && (
315	              <Field label="SMS Phone Number">
316	                <SettingsInput
317	                  value={smsPhone}
318	                  onChange={e => setSmsPhone(e.target.value)}
319	                  placeholder="0412 345 678"
320	                />
321	              </Field>
322	            )}
323	          </div>
324	        </SectionCard>
325	
326	        {/* ── AN-ACC Settings ── */}
327	        <SectionCard icon={DollarSign} title="AN-ACC Settings">
328	          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
329	            <Field label="AN-ACC Rate per Resident (AUD/day)" hint="Default: $220.00. Update if your Base Care Tariff changes.">
330	              <div className="relative">
331	                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-sm">$</span>
332	                <input
333	                  type="number"
334	                  value={anAccRate}
335	                  onChange={e => setAnAccRate(e.target.value)}
336	                  step="0.01"
337	                  min="0"
338	                  className="w-full border border-gray-200 rounded-lg pl-7 pr-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#22c55e]"
339	                />
340	              </div>
341	            </Field>
342	            <div className="flex items-end pb-0.5">
343	              <div className="bg-blue-50 rounded-lg p-3 w-full">
344	                <p className="text-xs text-blue-600 font-medium">Daily subsidy preview</p>
345	                <p className="text-lg font-bold text-blue-800 mt-0.5">
346	                  ${(parseFloat(anAccRate || 0) * parseInt(residents || 40)).toLocaleString('en-AU', { minimumFractionDigits: 2 })}
347	                </p>
348	                <p className="text-xs text-blue-500">{residents} residents × ${parseFloat(anAccRate || 0).toFixed(2)}</p>
349	              </div>
350	            </div>
351	          </div>
352	        </SectionCard>
353	
354	        {/* ── Save Button ── */}
355	        <div className="flex justify-end mb-8">
356	          <button
357	            type="submit"
358	            disabled={saving}
359	            className="flex items-center gap-2 px-6 py-2.5 bg-[#22c55e] text-white rounded-lg text-sm font-semibold hover:bg-green-600 active:bg-green-700 transition-colors disabled:opacity-60 shadow-sm w-full sm:w-auto justify-center"
360	          >
361	            {saving ? (
362	              <><span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> Saving…</>
363	            ) : saved ? (
364	              <><Check className="w-4 h-4" /> Settings Saved!</>
365	            ) : (
366	              <><Save className="w-4 h-4" /> Save Settings</>
367	            )}
368	          </button>
369	        </div>
370	      </form>
371	
372	      {/* ── Alert Recipients ───────────────────────────────────────────────── */}
373	      <SectionCard icon={Mail} title="Alert Recipients">
374	        <p className="text-sm text-gray-500 mb-5">
375	          Add email addresses and mobile numbers to receive daily compliance alerts at 07:00 AEST
376	        </p>
377	
378	        {/* Email Recipients */}
379	        <div className="mb-6">
380	          <div className="flex items-center gap-2 mb-3">
381	            <Mail className="w-3.5 h-3.5 text-gray-400" />
382	            <h3 className="text-sm font-semibold text-gray-700">Email Recipients</h3>
383	            <span className="text-xs text-gray-400">({emailRecipients.length}/5)</span>
384	          </div>
385	
386	          <div className="flex gap-2 mb-2">
387	            <input
388	              type="email"
389	              value={newEmail}
390	              onChange={e => { setNewEmail(e.target.value); setEmailError(''); }}
391	              onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), addEmail())}
392	              placeholder="Email address"
393	              className="flex-1 min-w-0 border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#22c55e] transition"
394	            />
395	            <button
396	              type="button"
397	              onClick={addEmail}
398	              disabled={emailRecipients.length >= 5}
399	              className="flex items-center gap-1.5 px-4 py-2 bg-[#22c55e] text-white rounded-lg text-sm font-medium hover:bg-green-600 active:bg-green-700 transition-colors disabled:opacity-40 shrink-0"
400	            >
401	              <Plus className="w-4 h-4" /> Add
402	            </button>
403	          </div>
404	          {emailError && <p className="text-xs text-red-500 mb-2">{emailError}</p>}
405	
406	          {emailRecipients.length > 0 && (
407	            <div className="space-y-2 mt-3">
408	              {emailRecipients.map(r => (
409	                <div key={r.id} className="flex items-center justify-between bg-gray-50 border border-gray-100 rounded-lg px-3 py-2.5">
410	                  <div className="flex items-center gap-3 min-w-0">
411	                    <Mail className="w-3.5 h-3.5 text-gray-400 shrink-0" />
412	                    <span className="text-sm text-gray-700 truncate">{r.email}</span>
413	                  </div>
414	                  <div className="flex items-center gap-3 ml-3 shrink-0">
415	                    <SmallToggle checked={r.active} onChange={() => toggleEmail(r.id)} />
416	                    <button
417	                      type="button"
418	                      onClick={() => removeEmail(r.id)}
419	                      className="w-6 h-6 flex items-center justify-center rounded-full bg-red-50 text-red-500 hover:bg-red-100 transition-colors"
420	                      title="Remove"
421	                    >
422	                      <X className="w-3.5 h-3.5" />
423	                    </button>
424	                  </div>
425	                </div>
426	              ))}
427	            </div>
428	          )}
429	        </div>
430	
431	        {/* SMS Recipients */}
432	        <div className="mb-6">
433	          <div className="flex items-center gap-2 mb-3">
434	            <Smartphone className="w-3.5 h-3.5 text-gray-400" />
435	            <h3 className="text-sm font-semibold text-gray-700">SMS Recipients</h3>
436	            <span className="text-xs text-gray-400">({smsRecipients.length}/3)</span>
437	          </div>
438	
439	          <div className="flex gap-2 mb-2">
440	            <input
441	              type="tel"
442	              value={newMobile}
443	              onChange={e => { setNewMobile(e.target.value); setMobileError(''); }}
444	              onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), addMobile())}
445	              placeholder="04XX XXX XXX"
446	              className="flex-1 min-w-0 border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#22c55e] transition"
447	            />
448	            <button
449	              type="button"
450	              onClick={addMobile}
451	              disabled={smsRecipients.length >= 3}
452	              className="flex items-center gap-1.5 px-4 py-2 bg-[#22c55e] text-white rounded-lg text-sm font-medium hover:bg-green-600 active:bg-green-700 transition-colors disabled:opacity-40 shrink-0"
453	            >
454	              <Plus className="w-4 h-4" /> Add
455	            </button>
456	          </div>
457	          {mobileError && <p className="text-xs text-red-500 mb-2">{mobileError}</p>}
458	
459	          {smsRecipients.length > 0 && (
460	            <div className="space-y-2 mt-3">
461	              {smsRecipients.map(r => (
462	                <div key={r.id} className="flex items-center justify-between bg-gray-50 border border-gray-100 rounded-lg px-3 py-2.5">
463	                  <div className="flex items-center gap-3 min-w-0">
464	                    <Smartphone className="w-3.5 h-3.5 text-gray-400 shrink-0" />
465	                    <span className="text-sm text-gray-700 truncate">{r.mobile}</span>
466	                  </div>
467	                  <div className="flex items-center gap-3 ml-3 shrink-0">
468	                    <SmallToggle checked={r.active} onChange={() => toggleMobile(r.id)} />
469	                    <button
470	                      type="button"
471	                      onClick={() => removeMobile(r.id)}
472	                      className="w-6 h-6 flex items-center justify-center rounded-full bg-red-50 text-red-500 hover:bg-red-100 transition-colors"
473	                      title="Remove"
474	                    >
475	                      <X className="w-3.5 h-3.5" />
476	                    </button>
477	                  </div>
478	                </div>
479	              ))}
480	            </div>
481	          )}
482	        </div>
483	
484	        <div className="flex justify-end">
485	          <SaveButton saving={recipientsSaving} saved={recipientsSaved} onClick={handleRecipientsSave} label="Save Recipients" />
486	        </div>
487	      </SectionCard>
488	
489	    </div>
490	  );
491	}
