'use client';

import { useState, useEffect, useCallback } from 'react';
import { Bell, CheckCircle, AlertTriangle, Mail, RefreshCw, Zap, X, Database } from 'lucide-react';
import { alerts as dummyAlerts } from '@/lib/dummyData';
import { getAlerts, saveAlert, mapAlert } from '@/lib/db';
import { SEED_FACILITY_ID } from '@/lib/seedData';

function formatDate(iso) {
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

function Toast({ toast, onDismiss }) {
  if (!toast) return null;
  const isError = toast.type === 'error';
  return (
    <div className={`fixed bottom-24 md:bottom-6 left-4 right-4 md:left-1/2 md:right-auto md:-translate-x-1/2 z-50 flex items-start gap-3 px-4 py-3.5 rounded-xl shadow-lg border text-sm font-medium md:max-w-sm transition-all
      ${isError ? 'bg-red-50 border-red-200 text-red-800' : 'bg-green-50 border-green-200 text-green-800'}`}
    >
      {isError
        ? <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5 text-red-500" />
        : <CheckCircle  className="w-4 h-4 shrink-0 mt-0.5 text-green-600" />
      }
      <span className="flex-1">{toast.message}</span>
      <button onClick={onDismiss} className="shrink-0 opacity-60 hover:opacity-100 transition-opacity ml-1">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

export default function AlertsPage() {
  const [alerts, setAlerts]         = useState(dummyAlerts);
  const [usingDb, setUsingDb]       = useState(false);
  const [dbLoading, setDbLoading]   = useState(true);
  const [generating, setGenerating] = useState(false);
  const [generated, setGenerated]   = useState(false);
  const [toast, setToast]           = useState(null);

  // ── Load alerts from Supabase ───────────────────────────────────────────────
  const loadFromDb = useCallback(async () => {
    setDbLoading(true);
    try {
      const { data, error } = await getAlerts(SEED_FACILITY_ID);
      if (!error && data && data.length > 0) {
        setAlerts(data.map(mapAlert));
        setUsingDb(true);
      }
    } catch {
      // keep dummy data
    } finally {
      setDbLoading(false);
    }
  }, []);

  useEffect(() => { loadFromDb(); }, [loadFromDb]);

  function showToast(message, type = 'success') {
    setToast({ message, type });
    setTimeout(() => setToast(null), 5000);
  }

  // ── Generate alert ──────────────────────────────────────────────────────────
  async function handleGenerate() {
    setGenerating(true);
    setGenerated(false);

    try {
      const res  = await fetch('/api/alerts/send', { method: 'POST' });
      const data = await res.json();

      if (!res.ok || data.error) throw new Error(data.error || 'Failed to send alert.');

      const newAlert = data.alert;

      // Save to Supabase if connected
      if (usingDb) {
        const { data: saved } = await saveAlert(SEED_FACILITY_ID, {
          date:           newAlert.date,
          status:         newAlert.status,
          title:          newAlert.title,
          message:        newAlert.message,
          gaps:           newAlert.gaps           ?? [],
          suggestedStaff: newAlert.suggestedStaff ?? [],
          sentViaEmail:   true,
        });
        if (saved) {
          setAlerts(prev => [mapAlert(saved), ...prev]);
          setGenerated(true);
          showToast(`Alert sent to ${data.toEmail} and saved to database`);
          setTimeout(() => setGenerated(false), 3000);
          return;
        }
      }

      // Fallback: add locally
      setAlerts(prev => [newAlert, ...prev]);
      setGenerated(true);
      showToast(`Alert sent to ${data.toEmail}`);
      setTimeout(() => setGenerated(false), 3000);
    } catch (err) {
      showToast(err.message || 'Failed to send alert. Please try again.', 'error');
    } finally {
      setGenerating(false);
    }
  }

  const onTrackCount = alerts.filter(a => a.status === 'On Track').length;
  const actionCount  = alerts.filter(a => a.status === 'Action Needed').length;

  return (
    <div className="p-4 md:p-6 max-w-4xl mx-auto">

      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
        <div>
          <div className="flex items-center gap-2 flex-wrap">
            <h1 className="text-xl font-bold text-gray-900">AI Shift Gap Alerts</h1>
            {usingDb ? (
              <span className="flex items-center gap-1 px-2 py-0.5 bg-green-100 text-green-700 text-xs font-semibold rounded-full border border-green-200">
                <Database className="w-3 h-3" /> Live DB
              </span>
            ) : (
              <span className="px-2 py-0.5 bg-blue-100 text-blue-700 text-xs font-semibold rounded-full border border-blue-200">Demo Data</span>
            )}
          </div>
          <p className="text-sm text-gray-500 mt-0.5">Daily compliance analysis — sent at 07:00 AEST</p>
        </div>
        <div className="flex gap-2">
          {usingDb && (
            <button onClick={loadFromDb} disabled={dbLoading} className="flex items-center gap-1.5 px-3 py-2 text-sm border border-gray-200 rounded-lg text-gray-600 hover:bg-gray-50 transition-colors disabled:opacity-50">
              <RefreshCw className={`w-4 h-4 ${dbLoading ? 'animate-spin' : ''}`} />
            </button>
          )}
          <button onClick={handleGenerate} disabled={generating}
            className="flex items-center justify-center gap-2 px-4 py-2.5 bg-[#1e293b] text-white rounded-lg text-sm font-semibold hover:bg-slate-700 active:bg-slate-800 transition-colors disabled:opacity-60 flex-1 sm:flex-none">
            {generating
              ? <><RefreshCw className="w-4 h-4 animate-spin" /> Sending alert…</>
              : generated
                ? <><CheckCircle className="w-4 h-4" /> Alert Sent!</>
                : <><Zap className="w-4 h-4" /> Generate Alert Now</>}
          </button>
        </div>
      </div>

      {/* ── Summary ── */}
      <div className="grid grid-cols-3 gap-3 md:gap-4 mb-6">
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 card-hover">
          <p className="text-xs text-gray-500 uppercase tracking-wide">Total Alerts</p>
          <p className="text-xl md:text-2xl font-bold text-gray-900 mt-1">{alerts.length}</p>
          <p className="text-xs text-gray-400 mt-0.5">Last 7 days</p>
        </div>
        <div className="stat-gradient-green rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 card-hover">
          <p className="text-xs text-gray-500 uppercase tracking-wide">On Track</p>
          <p className="text-xl md:text-2xl font-bold text-green-600 mt-1">{onTrackCount}</p>
        </div>
        <div className="stat-gradient-amber rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 card-hover">
          <p className="text-xs text-gray-500 uppercase tracking-wide">Action Needed</p>
          <p className="text-xl md:text-2xl font-bold text-amber-600 mt-1">{actionCount}</p>
        </div>
      </div>

      {/* ── Alerts List ── */}
      <div className="space-y-3 md:space-y-4">
        {alerts.map(alert => (
          <div key={alert.id}
            className={`bg-white rounded-xl shadow-sm border overflow-hidden card-hover ${alert.status === 'Action Needed' ? 'border-amber-200' : 'border-gray-100'}`}>
            {/* Card header */}
            <div className={`px-4 md:px-5 py-3 flex items-start justify-between gap-3 ${alert.status === 'Action Needed' ? 'bg-amber-50' : 'bg-green-50'}`}>
              <div className="flex items-start gap-2 flex-wrap min-w-0">
                {alert.status === 'Action Needed'
                  ? <AlertTriangle className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
                  : <CheckCircle  className="w-4 h-4 text-green-600  shrink-0 mt-0.5" />
                }
                <span className="text-sm font-semibold text-gray-900 break-words">{alert.title}</span>
                <span className={`px-2 py-0.5 rounded-full text-xs font-bold shrink-0 ${alert.status === 'Action Needed' ? 'bg-amber-200 text-amber-800' : 'bg-green-200 text-green-800'}`}>
                  {alert.status}
                </span>
              </div>
              <div className="flex items-center gap-2 shrink-0 flex-wrap justify-end">
                <span className="text-xs text-gray-500 whitespace-nowrap">{formatDate(alert.date)}</span>
                {alert.sentViaEmail && (
                  <span className="flex items-center gap-1 px-2 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs font-medium whitespace-nowrap">
                    <Mail className="w-3 h-3" /> Email
                  </span>
                )}
              </div>
            </div>

            {/* Card body */}
            <div className="px-4 md:px-5 py-4 space-y-3 md:space-y-4">
              <div className="flex gap-3">
                <div className="w-7 h-7 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center shrink-0 mt-0.5">
                  <Zap className="w-3.5 h-3.5 text-white" />
                </div>
                <div className="min-w-0">
                  <p className="text-xs font-semibold text-gray-500 mb-1">CareMinutes AI Analysis</p>
                  <p className="text-sm text-gray-700 leading-relaxed">{alert.message}</p>
                </div>
              </div>

              {alert.gaps && alert.gaps.length > 0 && (
                <div className="bg-red-50 border border-red-100 rounded-lg p-3">
                  <p className="text-xs font-semibold text-red-700 mb-2 uppercase tracking-wide">Identified Gaps</p>
                  <ul className="space-y-1">
                    {alert.gaps.map((gap, i) => (
                      <li key={i} className="text-xs text-red-700 flex items-start gap-1.5">
                        <span className="mt-0.5 shrink-0">•</span><span>{gap}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {alert.suggestedStaff && alert.suggestedStaff.length > 0 && (
                <div className="bg-blue-50 border border-blue-100 rounded-lg p-3">
                  <p className="text-xs font-semibold text-blue-700 mb-2 uppercase tracking-wide">Suggested Staff to Contact</p>
                  <ul className="space-y-1">
                    {alert.suggestedStaff.map((s, i) => (
                      <li key={i} className="text-xs text-blue-700 flex items-start gap-1.5">
                        <span className="mt-0.5 shrink-0">→</span><span>{s}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* ── Empty state ── */}
      {alerts.length === 0 && (
        <div className="text-center py-20">
          <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-4">
            <Bell className="w-8 h-8 text-gray-300" />
          </div>
          <p className="text-gray-500 font-medium">No alerts yet</p>
          <p className="text-sm text-gray-400 mt-1">Alerts are generated daily at 07:00 AEST</p>
        </div>
      )}

      <Toast toast={toast} onDismiss={() => setToast(null)} />
    </div>
  );
}

import { Resend } from 'resend';
import { shiftsByDate, facility, alerts as dummyAlerts } from '@/lib/dummyData';
import { calculateDayCompliance, formatAUD, formatPct } from '@/lib/compliance';
import { saveAlert } from '@/lib/db';
import { SEED_FACILITY_ID } from '@/lib/seedData';

const TODAY = '2026-04-02';

function toDisplayDate(iso) {
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

function buildEmailHtml({ alert, compliance, toEmail }) {
  const statusColour  = alert.status === 'On Track' ? '#16a34a' : '#d97706';
  const statusBg      = alert.status === 'On Track' ? '#f0fdf4' : '#fffbeb';
  const statusBorder  = alert.status === 'On Track' ? '#bbf7d0' : '#fde68a';
  const isCompliant   = alert.status === 'On Track';

  const gapsHtml = alert.gaps && alert.gaps.length > 0
    ? `
      <div style="background:#fff1f2;border:1px solid #fecdd3;border-radius:8px;padding:16px;margin:16px 0;">
        <p style="margin:0 0 10px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#be123c;">Identified Gaps</p>
        <ul style="margin:0;padding-left:18px;">
          ${alert.gaps.map(g => `<li style="font-size:14px;color:#9f1239;margin-bottom:4px;">${g}</li>`).join('')}
        </ul>
      </div>`
    : '';

  const staffHtml = alert.suggestedStaff && alert.suggestedStaff.length > 0
    ? `
      <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:16px;margin:16px 0;">
        <p style="margin:0 0 10px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#1d4ed8;">Suggested Staff to Contact</p>
        <ul style="margin:0;padding-left:18px;">
          ${alert.suggestedStaff.map(s => `<li style="font-size:14px;color:#1e40af;margin-bottom:4px;">${s}</li>`).join('')}
        </ul>
      </div>`
    : '';

  const penaltyHtml = compliance.penaltyAmount > 0
    ? `<tr>
        <td style="padding:8px 12px;font-size:13px;color:#6b7280;border-bottom:1px solid #f3f4f6;">Penalty at Risk</td>
        <td style="padding:8px 12px;font-size:13px;font-weight:700;color:#dc2626;border-bottom:1px solid #f3f4f6;">${formatAUD(compliance.penaltyAmount)}</td>
       </tr>`
    : `<tr>
        <td style="padding:8px 12px;font-size:13px;color:#6b7280;border-bottom:1px solid #f3f4f6;">Penalty at Risk</td>
        <td style="padding:8px 12px;font-size:13px;font-weight:700;color:#16a34a;border-bottom:1px solid #f3f4f6;">$0.00 — No penalty</td>
       </tr>`;

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CareMinutes.ai — Daily Compliance Alert</title>
</head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;padding:32px 16px;">
    <tr>
      <td align="center">
        <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;">

          <!-- Header -->
          <tr>
            <td style="background:#ffffff;border-radius:12px 12px 0 0;padding:28px 32px 20px;border-bottom:3px solid #22c55e;">
              <table width="100%" cellpadding="0" cellspacing="0">
                <tr>
                  <td>
                    <span style="font-size:22px;font-weight:800;color:#22c55e;letter-spacing:-0.5px;">CareMinutes</span><span style="font-size:22px;font-weight:800;color:#1e293b;">.ai</span>
                    <p style="margin:4px 0 0;font-size:12px;color:#94a3b8;font-weight:500;">Australian Aged Care Compliance</p>
                  </td>
                  <td align="right">
                    <span style="display:inline-block;padding:6px 14px;border-radius:999px;background:${statusBg};border:1px solid ${statusBorder};color:${statusColour};font-size:12px;font-weight:700;">
                      ${alert.status}
                    </span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <!-- Facility & Date -->
          <tr>
            <td style="background:#ffffff;padding:20px 32px 0;">
              <table width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:14px 16px;">
                <tr>
                  <td>
                    <p style="margin:0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#94a3b8;">Facility</p>
                    <p style="margin:4px 0 0;font-size:16px;font-weight:700;color:#1e293b;">${facility.name}</p>
                  </td>
                  <td align="right">
                    <p style="margin:0;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#94a3b8;">Report Date</p>
                    <p style="margin:4px 0 0;font-size:16px;font-weight:700;color:#1e293b;">${toDisplayDate(alert.date)}</p>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <!-- Compliance Summary -->
          <tr>
            <td style="background:#ffffff;padding:20px 32px 0;">
              <p style="margin:0 0 12px;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#475569;">Compliance Summary</p>
              <table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;">
                <tr style="background:#f8fafc;">
                  <td style="padding:8px 12px;font-size:13px;color:#6b7280;border-bottom:1px solid #f3f4f6;">Total Care Minutes</td>
                  <td style="padding:8px 12px;font-size:13px;font-weight:700;color:#1e293b;border-bottom:1px solid #f3f4f6;">${compliance.totalMinutes.toLocaleString('en-AU')} min <span style="font-weight:400;color:#6b7280;">(target: ${compliance.targetMinutes.toLocaleString('en-AU')} min)</span></td>
                </tr>
                <tr>
                  <td style="padding:8px 12px;font-size:13px;color:#6b7280;border-bottom:1px solid #f3f4f6;">RN Minutes Delivered</td>
                  <td style="padding:8px 12px;font-size:13px;font-weight:700;color:#1e293b;border-bottom:1px solid #f3f4f6;">${compliance.rnMinutes.toLocaleString('en-AU')} min <span style="font-weight:400;color:#6b7280;">(target: ${compliance.rnTargetMinutes.toLocaleString('en-AU')} min)</span></td>
                </tr>
                <tr style="background:#f8fafc;">
                  <td style="padding:8px 12px;font-size:13px;color:#6b7280;border-bottom:1px solid #f3f4f6;">Overall Compliance</td>
                  <td style="padding:8px 12px;font-size:13px;font-weight:700;border-bottom:1px solid #f3f4f6;">
                    <span style="color:${isCompliant ? '#16a34a' : '#d97706'};">${formatPct(compliance.compliancePct)}</span>
                    <span style="display:inline-block;margin-left:8px;padding:2px 8px;border-radius:999px;font-size:11px;font-weight:700;background:${isCompliant ? '#dcfce7' : '#fef3c7'};color:${isCompliant ? '#15803d' : '#92400e'};">${compliance.ragStatus}</span>
                  </td>
                </tr>
                ${penaltyHtml}
              </table>
            </td>
          </tr>

          <!-- AI Analysis -->
          <tr>
            <td style="background:#ffffff;padding:20px 32px 0;">
              <p style="margin:0 0 12px;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#475569;">AI Analysis</p>
              <div style="background:#fafafa;border:1px solid #e2e8f0;border-radius:8px;padding:16px;">
                <table cellpadding="0" cellspacing="0">
                  <tr>
                    <td style="vertical-align:top;padding-right:12px;">
                      <div style="width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,#3b82f6,#7c3aed);display:flex;align-items:center;justify-content:center;">
                        <span style="color:white;font-size:14px;font-weight:700;">⚡</span>
                      </div>
                    </td>
                    <td>
                      <p style="margin:0 0 4px;font-size:11px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.04em;">CareMinutes AI</p>
                      <p style="margin:0;font-size:14px;color:#374151;line-height:1.6;">${alert.message}</p>
                    </td>
                  </tr>
                </table>
              </div>
              ${gapsHtml}
              ${staffHtml}
            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td style="background:#ffffff;border-radius:0 0 12px 12px;padding:24px 32px;margin-top:8px;border-top:1px solid #f1f5f9;">
              <p style="margin:0;font-size:12px;color:#94a3b8;line-height:1.6;">
                Sent by <strong style="color:#22c55e;">CareMinutes.ai</strong> · Australian Aged Care Compliance<br>
                This alert was generated for <strong>${facility.name}</strong> and delivered to ${toEmail}<br>
                Daily alerts are sent at 07:00 AEST · <a href="#" style="color:#22c55e;text-decoration:none;">Manage preferences</a>
              </p>
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
}

export async function POST() {
  const apiKey   = process.env.RESEND_API_KEY;
  const fromEmail = process.env.ALERT_FROM_EMAIL;
  const toEmail   = process.env.ALERT_TO_EMAIL;

  if (!apiKey || !fromEmail || !toEmail) {
    return Response.json(
      { error: 'Missing email configuration. Check RESEND_API_KEY, ALERT_FROM_EMAIL, ALERT_TO_EMAIL in .env.local.' },
      { status: 500 }
    );
  }

  // Build compliance data for today
  const todayShifts = shiftsByDate[TODAY] || [];
  const compliance = calculateDayCompliance(todayShifts, facility.residentCount);

  // Use the most recent (today's) alert as the AI analysis content
  const alert = dummyAlerts[0];

  const html = buildEmailHtml({ alert, compliance, toEmail });

  const resend = new Resend(apiKey);

  const { data, error } = await resend.emails.send({
    from: fromEmail,
    to: toEmail,
    subject: `CareMinutes.ai — Daily Compliance Alert ${facility.name}`,
    html,
  });

  if (error) {
    console.error('[alerts/send] Resend error:', error);
    return Response.json({ error: error.message || 'Failed to send email.' }, { status: 502 });
  }

  const alertPayload = {
    date:           TODAY,
    status:         alert.status,
    title:          `AI analysis sent — ${toDisplayDate(TODAY)}`,
    message:        alert.message,
    gaps:           alert.gaps           ?? [],
    suggestedStaff: alert.suggestedStaff ?? [],
    sentViaEmail:   true,
  };

  // Persist to Supabase (best-effort — don't fail the response if DB is unavailable)
  try {
    await saveAlert(SEED_FACILITY_ID, alertPayload);
  } catch (dbErr) {
    console.warn('[alerts/send] Could not save alert to DB:', dbErr?.message);
  }

  return Response.json({
    success: true,
    messageId: data?.id,
    toEmail,
    alert: {
      id: `alert-sent-${Date.now()}`,
      ...alertPayload,
    },
  });
}

