const STATES = ['NSW','VIC','QLD','SA','WA','TAS','NT','ACT'];

const DEFAULT_EMAIL_RECIPIENTS = [
  { id: 1, email: 'jennifer@sunriseagedcare.com.au', active: true },
  { id: 2, email: 'operations@sunriseagedcare.com.au', active: true },
