              <><Check className="w-4 h-4" /> Settings Saved!</>
            ) : (
              <><Save className="w-4 h-4" /> Save Settings</>
            )}
          </button>
        </div>
      </form>

      {/* ── Alert Recipients ───────────────────────────────────────────────── */}
      <SectionCard icon={Mail} title="Alert Recipients">
        <p className="text-sm text-gray-500 mb-5">
